import json, urllib.request, urllib.error, time
from datetime import datetime, timezone
BASE='http://localhost:8080'
def token():
    req=urllib.request.Request(BASE+'/token',data=b'',method='POST')
    with urllib.request.urlopen(req,timeout=15) as r: return json.load(r)['token']
tok=token()
def get_customer(cid):
    global tok
    for _ in range(5):
        req=urllib.request.Request(BASE+'/customers/'+cid,headers={'Authorization':'Bearer '+tok})
        try:
            with urllib.request.urlopen(req,timeout=15) as r:return json.load(r)
        except urllib.error.HTTPError as e:
            try: d=json.loads(e.read().decode())
            except: d={}
            if e.code==429:
                delay=float(d.get('retry_after',d.get('wait_seconds',d.get('retry',1))))
                print('customer rate limit, wait',delay,flush=True);time.sleep(delay);tok=token()
            elif e.code in (401,403): tok=token()
            else: raise RuntimeError((e.code,cid,d))
    raise RuntimeError('customer retries exhausted '+cid)
raw=json.load(open('/tmp/orders_all.json'))
seen=set(); orders=[]; duplicates=0
for page in raw:
    for o in page:
        if o['id'] in seen: duplicates+=1
        else: seen.add(o['id']); orders.append(o)
start=datetime(2025,3,1,tzinfo=timezone.utc); end=datetime(2025,6,1,tzinfo=timezone.utc)
qual=[]
for o in orders:
    if o['status']"'!='"'shipped': continue
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if start<=dt<end: qual.append(o)
ids=sorted({o['customer_id'] for o in qual})
customers={}
for i,cid in enumerate(ids,1):
    customers[cid]=get_customer(cid)
    if i<len(ids): time.sleep(.5)
regions={'north':0,'south':0,'east':0,'west':0}
total=0
for o in qual:
    c=customers[o['customer_id']]
    # integer half-up: cents * (100-discount) / 100
    v=(o['amount_cents']*(100-c['discount_pct'])+50)//100
    regions[c['region']]+=v; total+=v
result={'total_cents':total,'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
assert sum(regions.values())==total
assert len(seen)==len(orders)
assert set(result)=={'total_cents','order_count','duplicates_skipped','by_region'}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result,indent=2))
print('unique listings',len(orders),'duplicates skipped',duplicates,'qualified',len(qual),'customers fetched',len(customers))
print('status counts', {s:sum(o['status']==s for o in orders) for s in ('shipped','placed','cancelled','returned')})
print('qualifying UTC range anomalies', [(o['id'],o['placed_at']) for o in qual if datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).tzinfo is None])
